'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `key2ind` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'key2ind' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.key2ind ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.key2ind.call( value, 'x' );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not a string', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		5,
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.key2ind( value );
		};
	}
});

tape( 'the method converts a field name to a tuple index', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	t.strictEqual( p.key2ind( 'x' ), 0, 'returns expected value' );
	t.strictEqual( p.key2ind( 'y' ), 1, 'returns expected value' );
	t.strictEqual( p.key2ind( 'z' ), 2, 'returns expected value' );
	t.end();
});

tape( 'the method returns `-1` if provided an unknown field name', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	t.strictEqual( p.key2ind( 'w' ), -1, 'returns expected value' );
	t.strictEqual( p.key2ind( 'foo' ), -1, 'returns expected value' );
	t.end();
});
